1383	  /// Show a surface-reported command title on its tab; directory/prompt titles are ignored so the
1384	  /// command sticks until `command_finished` clears it.
1385	  private func updateTitle(_ title: String, forTab tabID: TerminalTab.ID, target: TerminalTarget.ID)
1386	  {
1387	    guard let tab = tabsByTarget[target]?[tabID], case .terminal(let s) = tab.content else {
1388	      return
1389	    }
1390	    let trimmed = title.trimmingCharacters(in: .whitespacesAndNewlines)
1391	    guard !trimmed.isEmpty, !Self.isDirectoryTitle(trimmed, cwd: s.view.lastKnownCwd) else {
1392	      return
1393	    }
1394	    // Read once — `foregroundTool` used to re-derive this internally via a second live PID read, a
1395	    // TOCTOU gap where the foreground process could differ between the two reads (review finding).
1396	    let foregroundExecutableName = s.view.foregroundExecutableName
1397	    let detectedAgent =
1398	      s.view.foregroundAgentBackend ?? AgentTitleRecognition.backend(for: trimmed)
1399	    let detectedTool =
1400	      ToolLogoRegistry.tool(forExecutableName: foregroundExecutableName)
1401	      ?? ToolLogoRegistry.tool(forTitle: trimmed)
1402	    guard
1403	      s.liveTitle != trimmed || (s.activeAgentBackend == nil && detectedAgent != nil)
1404	        || (s.activeTool == nil && detectedTool != nil)
1405	    else {
1406	      return
1407	    }
1408	    // Usage tracking for issue #141: a genuinely new foreground command that ISN'T in the curated
1409	    // registry at all (not merely missing its fetched asset — `matchingEntry` is the ungated check)
1410	    // gets tallied, so a periodic look at the file shows which non-curated tools are worth adding
1411	    // next. Gated on `s.liveTitle != trimmed` (a real title change, not a repaint of the same still-
1412	    // unrecognized command) so a long-running unmatched program is counted once, not per repaint.
1413	    if s.liveTitle != trimmed, detectedTool == nil,
1414	      let rawName = foregroundExecutableName,
1415	      ToolLogoRegistry.matchingEntry(forExecutableName: rawName) == nil
1416	    {
1417	      recordUnrecognizedTool(rawName)
1418	    }
1419	    mutateTerminalState(tabID, target: target) {
1420	      $0.liveTitle = trimmed
1421	      if $0.activeAgentBackend == nil { $0.activeAgentBackend = detectedAgent }
1422	      if $0.activeTool == nil { $0.activeTool = detectedTool }
1423	    }
1424	  }
